FILL = {'Done': 'C6E0B4', 'In progress': 'FFE699', 'Waiting for owner': 'F8CBAD', 'Open': 'FFFFFF', 'Critical': 'F8CBAD', 'High': 'FFE699', 'Medium': 'DDEBF7', 'Low': 'EDEDED', 'Met': 'C6E0B4', 'Partly': 'FFE699', 'Not met': 'F8CBAD'}

def sheet(name, header, rows, widths, colour_col=None):
    ws = wb.create_sheet(name)
    ws.append(header)
    for r in rows:
        ws.append(r)
    for c in ws[1]:
        c.font = Font(bold=True, color='FFFFFF')
        c.fill = PatternFill('solid', fgColor='305496')
        c.alignment = Alignment(wrap_text=True, vertical='top')
    for i, w in enumerate(widths, 1):
        ws.column_dimensions[get_column_letter(i)].width = w
    for row in ws.iter_rows(min_row=2):
        for c in row:
            c.alignment = Alignment(wrap_text=True, vertical='top')
        if colour_col is not None:
            v = row[colour_col].value
            if v in FILL:
                row[colour_col].fill = PatternFill('solid', fgColor=FILL[v])
    ws.freeze_panes = 'A2'
    ws.auto_filter.ref = ws.dimensions
    return ws

